long long count_odd_divisors(long long x) {
    long long cnt = 0;
    for (long long i = 1; i * i <= x; i++) {
        if (x % i == 0) {
            if (i % 2 == 1) cnt++;
            long long j = x / i;
            if (j != i && j % 2 == 1) cnt++;
        }
    }
    return cnt;
}

