ll countWays(ll v) {
    // count pairs (n, s) with n*s = 2v, n < s, n and s have different parity
    ll tv = 2 * v;
    ll cnt = 0;
    for (ll n = 1; n * n <= tv; n++) {
        if (tv % n == 0) {
            ll s = tv / n;
            if (s > n && (n % 2) != (s % 2)) {
                cnt++;
            }
        }
    }
    return cnt;
}

