using int64 = long long;
using i128 = __int128_t;

static inline long long isqrtll(long long x) {
    long long r = sqrt((long double)x);
    while ((r + 1) > 0 && (i128)(r + 1) * (r + 1) <= x) ++r;
    while ((i128)r * r > x) --r;
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long S;
    cin >> S;

    // Sum over rectangle [a..b] x [c..d]:
    // (sum_{i=a}^b i) * (sum_{j=c}^d j)
    // Let X = sum_{i=a}^b i, Y = sum_{j=c}^d j. Then X * Y = S.
    //
    // So answer = sum over divisors X of S: ways(X) * ways(S/X),
    // where ways(n) = number of intervals [l..r], l<=r, positive integers,
    // such that l + (l+1) + ... + r = n.
    //
    // Classical fact:
    // number of representations of n as a sum of consecutive positive integers
    // equals the number of odd divisors of n.

    // Hence if odd_part(S) = product p_i^{e_i},
    // then ways(n) depends only on odd part of n:
    // ways(n) = number_of_divisors(odd_part(n)).
    //
    // We need sum_{X|S} d_odd(X) * d_odd(S/X).
    // Since this is multiplicative, for S = 2^k * product p_i^{e_i},
    // answer = (k+1) * product over odd p_i of:
    //   sum_{a=0}^{e_i} (a+1)(e_i-a+1)
    // Let e=e_i. Then this sum equals (e+1)(e+2)(e+3)/6.

    long long ans = 1;

    // factor out 2
    long long temp = S;
    int e2 = 0;
    while ((temp & 1LL) == 0) {
        temp >>= 1;
        ++e2;
    }
    ans *= (e2 + 1);

    // factor odd primes
    for (long long p = 3; (i128)p * p <= temp; p += 2) {
        if (temp % p == 0) {
            int e = 0;
            while (temp % p == 0) {
                temp /= p;
                ++e;
            }
            ans *= 1LL * (e + 1) * (e + 2) * (e + 3) / 6;
        }
    }
    if (temp > 1) {
        // odd prime with exponent 1
        ans *= 4; // (1+1)(1+2)(1+3)/6 = 4
    }

    cout << ans << '\n';
    return 0;
}

#include <stdio.h>

int count_ways(long long X) {
    int ways = 0;
    long long twoX = 2 * X;
    for (long long len = 1; len * len <= twoX; len++) {
        if (twoX % len == 0) {
            long long sum_val = twoX / len;
            if ((sum_val - len + 1) % 2 == 0) {
                long long a = (sum_val - len + 1) / 2;
                if (a >= 1) {
                    long long b = a + len - 1;
                    if (b >= a) ways++;
                }
            }
            long long len2 = twoX / len;
            if (len2 != len) {
                if ((twoX / len2 - len2 + 1) % 2 == 0) {
                    long long a = (twoX / len2 - len2 + 1) / 2;
                    if (a >= 1) {
                        long long b = a + len2 - 1;
                        if (b >= a) ways++;
                    }
                }
            }
        }
    }
    return ways;
}

int main() {
