typedef long long ll;

static ll isqrtll(ll x) {
    ll r = (ll)sqrt((long double)x);
    while ((r + 1) > 0 && (r + 1) <= x / (r + 1)) r++;
    while (r > x / r) r--;
    return r;
}

static ll count_pairs_with_product(ll n) {
    if (n <= 0) return 0;
    ll cnt = 0;
    ll lim = isqrtll(n);
    for (ll x = 1; x <= lim; x++) {
        if (n % x == 0) {
            ll y = n / x;
            if (x <= y) cnt++;
        }
    }
    return cnt;
}

int main(void) {
    ll S;
