    ll ans = 0;

    /* 
       Sum over rectangle [a..b] x [c..d]:
       (sum_{i=a}^b i) * (sum_{j=c}^d j)

       Let X = sum_{i=a}^b i, Y = sum_{j=c}^d j, so X*Y = S.
       Number of ways for a fixed X is the number of representations
       of X as sum of consecutive positive integers:
       X = a + (a+1) + ... + b, 1 <= a <= b.

       This count equals the number of odd divisors of X.
       Reason:
       X = k(2a+k-1)/2  <=>  2X = k * m, where m = 2a+k-1.
       Standard result: representations as consecutive positive integers
       are in bijection with odd divisors of X.

       Therefore answer = sum_{X|S} f(X) * f(S/X),
       where f(n) = number of odd divisors of n.

       If n = 2^t * m (m odd), then f(n) = d(m), the number of divisors of m.
    */

    for (ll x = 1; x <= isqrtll(S); x++) {
        if (S % x) continue;
        ll y = S / x;

        /* remove powers of 2 */
        ll ox = x;
        while ((ox & 1LL) == 0) ox >>= 1;

        ll oy = y;
        while ((oy & 1LL) == 0) oy >>= 1;

        ll fx = count_pairs_with_product(ox); /* not used directly */
        ll fy = count_pairs_with_product(oy); /* not used directly */

        /* number of divisors of odd part */
        ll dx = 0, dy = 0;
        {
            ll n = ox;
            dx = 1;
            for (ll p = 3; p * p <= n; p += 2) {
                if (n % p == 0) {
                    int e = 0;
                    while (n % p == 0) {
                        n /= p;
                        e++;
                    }
                    dx *= (e + 1);
                }
            }
            if (n > 1) dx *= 2;
        }
        {
            ll n = oy;
            dy = 1;
            for (ll p = 3; p * p <= n; p += 2) {
                if (n % p == 0) {
                    int e = 0;
                    while (n % p == 0) {
                        n /= p;
                        e++;
                    }
                    dy *= (e + 1);
                }
            }
            if (n > 1) dy *= 2;
        }

        if (x == y) ans += dx * dy;
        else ans += 2 * dx * dy;
    }

    printf("%lld\n", ans);
    return 0;
}

