import math

def count_pairs(n):
    """return number of (a,b) with a<=b and sum of a..b == n"""
    cnt = 0
    # k = length (b-a+1)
    # sum = k*(2a + k - 1)/2 = n
    # 2a = 2n/k - k + 1 must be even positive integer
    limit = int(math.isqrt(2 * n)) + 1
    for k in range(1, limit + 1):
        if (2 * n) % k != 0:
            continue
        if (2 * n // k - k + 1) % 2 != 0:
            continue
        a = (2 * n // k - k + 1) // 2
        if a >= 1:
            cnt += 1
    return cnt

