def count_ways(v):
    # Count pairs (k, m) with k*m = 2v, m > k >= 1, k and m have different parity
    target = 2 * v
    count = 0
    i = 1
    while i * i <= target:
        if target % i == 0:
            k, m = i, target // i
            if m > k and (k % 2) != (m % 2):
                count += 1
        i += 1
    return count

