public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int S = sc.nextInt();

        // Map from sum to count of (height, width) pairs for rows and columns
        Map<Long, Long> rowCount = new HashMap<>();

        // Maximum possible height/width: when a=1, sum grows ~ h^2, so h <= sqrt(2S)
        int maxHW = (int) Math.sqrt(2 * S) + 2;

        for (int h = 1; h <= maxHW; h++) {
            // rowSum = h * (2a + h - 1) / 2
            // For a >= 1:
            for (int a = 1; ; a++) {
                long sum = (long) h * (2L * a + h - 1) / 2;
                if (sum > S) break;
                rowCount.put(sum, rowCount.getOrDefault(sum, 0L) + 1);
            }
        }

        long result = 0;
        // Iterate over possible column sums
        for (int w = 1; w <= maxHW; w++) {
            for (int c = 1; ; c++) {
                long sum = (long) w * (2L * c + w - 1) / 2;
                if (sum > S) break;
                if (S % sum == 0) {
                    long needed = S / sum;
                    result += rowCount.getOrDefault(needed, 0L);
                }
            }
        }

        System.out.println(result);
    }
}

