public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long S = sc.nextLong();

        // Count number of (a,b) pairs with 1<=a<=b and R(a,b)=t for each divisor t of S
        // Then answer = sum over divisors d of S: count(d)*count(S/d)

        List<Long> divisors = new ArrayList<>();
        for (long i = 1; i * i <= S; i++) {
            if (S % i == 0) {
                divisors.add(i);
                if (i != S / i) divisors.add(S / i);
            }
        }

        long answer = 0;
        for (long d : divisors) {
            long e = S / d;
            answer += countWays(d) * countWays(e);
        }

        System.out.println(answer);
    }

    static long countWays(long t) {
        long count = 0;
        long twoT = 2 * t;
        for (long k = 1; k * k <= twoT; k++) {
            if (twoT % k == 0) {
                long s = twoT / k;
                if ((k % 2) != (s % 2) && s > k) count++;
                if (k != s) {
                    // swap: k2=s, s2=k
                    long k2 = s, s2 = k;
                    if ((k2 % 2) != (s2 % 2) && s2 > k2) count++;
                }
            }
        }
        return count;
    }
}

