public class Main {
    static final long MOD1 = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long S = fs.nextLong();

        // Sum over rectangle [a..b] x [c..d]:
        // ((a+b)(b-a+1)/2) * ((c+d)(d-c+1)/2) = S
        //
        // Let x = b-a+1, y = a+b, u = d-c+1, v = c+d.
        // Then x,y have same parity and x>=1, y>=x.
        // Similarly for u,v.
        // Rectangle sum = (x*y/2) * (u*v/2) = S.
        //
        // Define p = x*y, q = u*v. Then p*q = 4S.
        // For each p, number of (a,b) is number of factorizations p=x*y
        // with x,y same parity and y>=x, which equals the number of ways to
        // represent p/2 as T * L where T=(a+b)(b-a+1)/2? More directly:
        //
        // For interval [a..b], sum i from a to b = n.
        // Then rectangle sum = n * m where m is sum c..d.
        // So answer = sum_{n|S} f(n) * f(S/n),
        // where f(n) = number of intervals [l..r], 1<=l<=r, with sum l+...+r = n.
        //
        // Classical fact: f(n) = number of odd divisors of n.
        //
        // Therefore answer = sum_{d|S} oddDivCount(d) * oddDivCount(S/d).
        // This arithmetic function is multiplicative.
        //
        // If S = 2^a * prod p_i^{e_i} (odd p_i),
        // oddDivCount(n) ignores power of 2.
        // Let g(S) = sum_{d|S} oddDivCount(d) * oddDivCount(S/d).
        // For prime powers:
        // - for 2^a: contribution = a+1
        // - for odd p^e: contribution = sum_{i=0}^e (i+1)(e-i+1)
        //   = (e+1)(e+2)(e+3)/6
        //
        // Final answer is product of these contributions.

        long ans = 1;

        int twoExp = 0;
        while ((S & 1L) == 0) {
            twoExp++;
            S >>= 1;
        }
        ans *= (twoExp + 1L);

        for (long p = 3; p * p <= S; p += 2) {
            if (S % p == 0) {
                int e = 0;
                while (S % p == 0) {
                    S /= p;
                    e++;
                }
                ans *= oddPrimeContribution(e);
            }
        }
        if (S > 1) {
            ans *= oddPrimeContribution(1);
        }

        System.out.println(ans);
    }

    static long oddPrimeContribution(int e) {
        // (e+1)(e+2)(e+3)/6
        long a = e + 1L, b = e + 2L, c = e + 3L;
        return a * b * c / 6L;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
